import{_ as n,o as a,c as t,ah as s}from"./chunks/framework.ChH6X6u6.js";const c=JSON.parse('{"title":"Paiement en ligne","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/paiement-en-ligne.md","filePath":"src/guide/admin/paiement-en-ligne.md"}'),i={name:"guide/admin/paiement-en-ligne.md"};function r(o,e,l,u,p,m){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="paiement-en-ligne" tabindex="-1">Paiement en ligne <a class="header-anchor" href="#paiement-en-ligne" aria-label="Permalink to &quot;Paiement en ligne&quot;">​</a></h1><p>Le paiement en ligne permet aux parents de régler les frais de scolarité depuis leur espace, par mobile money (Flooz ou Mixx by Yass). Tant qu&#39;il n&#39;est pas activé, le bouton <strong>Payer en ligne</strong> n&#39;apparaît pas côté parents : ils paient à la caisse, comme d&#39;habitude.</p><p>La page s&#39;ouvre par <strong>Finances → Paiement en ligne</strong>. Elle n&#39;est visible que par les administrateurs.</p><h2 id="ou-en-est-votre-etablissement" tabindex="-1">Où en est votre établissement <a class="header-anchor" href="#ou-en-est-votre-etablissement" aria-label="Permalink to &quot;Où en est votre établissement&quot;">​</a></h2><p>Le haut de la page résume la situation :</p><ul><li><strong>Non activé</strong> : les parents ne peuvent pas encore payer en ligne ;</li><li><strong>Actif</strong> : l&#39;opérateur de paiement, les moyens acceptés, la majoration éventuelle (voir plus bas), la date d&#39;activation et qui l&#39;a configuré ;</li><li><strong>Suspendu</strong> : le paiement en ligne a été coupé, sans perdre sa configuration. Il peut être réactivé à tout moment.</li></ul><h2 id="demander-l-activation" tabindex="-1">Demander l&#39;activation <a class="header-anchor" href="#demander-l-activation" aria-label="Permalink to &quot;Demander l&#39;activation&quot;">​</a></h2><p>Le paiement en ligne passe par un compte marchand ouvert au nom de l&#39;établissement chez l&#39;opérateur de paiement. C&#39;est edPage qui l&#39;ouvre et le relie à ERA.</p><ol><li>Remplissez le formulaire <strong>Demander l&#39;activation</strong> : <ul><li>la <strong>raison sociale</strong> de l&#39;établissement ;</li><li>le <strong>responsable légal</strong> ;</li><li>le <strong>RCCM</strong> et le <strong>NIF</strong>, si vous les avez sous la main ;</li><li>un <strong>téléphone</strong> et un <strong>e-mail</strong> de contact ;</li><li>le <strong>numéro de reversement des fonds</strong>, celui sur lequel l&#39;opérateur vous reversera les paiements des parents ;</li><li>un <strong>message</strong>, si besoin.</li></ul></li><li>Cliquez sur <strong>Envoyer la demande</strong>.</li></ol><p>edPage vous recontacte ensuite pour convenir de la mise en place : c&#39;est un service payant, réglé directement auprès d&#39;edPage, en dehors de la plateforme. Les pièces justificatives demandées par l&#39;opérateur sont échangées à ce moment-là.</p><p>Pendant le traitement, la page indique où en est votre demande et affiche les éventuelles précisions d&#39;edPage. Une fois le compte ouvert, edPage active le paiement en ligne et les administrateurs reçoivent un e-mail : les parents voient le bouton <strong>Payer en ligne</strong> dès cet instant.</p><div class="info custom-block"><p class="custom-block-title">Vous ne voyez pas le formulaire ?</p><p>Il disparaît quand le paiement en ligne est actif, et tant qu&#39;une demande est en cours de traitement. Sur une installation autonome, il n&#39;apparaît que si l&#39;adresse d&#39;envoi des demandes a été renseignée sur le serveur : contactez edPage directement si ce n&#39;est pas le cas.</p></div><h2 id="la-majoration-des-paiements-en-ligne" tabindex="-1">La majoration des paiements en ligne <a class="header-anchor" href="#la-majoration-des-paiements-en-ligne" aria-label="Permalink to &quot;La majoration des paiements en ligne&quot;">​</a></h2><p>L&#39;opérateur prélève une commission sur chaque transaction. Pour ne pas alourdir les frais payés à la caisse, une <strong>majoration</strong> peut s&#39;appliquer aux seuls paiements en ligne : avec une majoration de 2,5 %, un parent qui règle 50 000 F en ligne est débité de 51 250 F, et c&#39;est bien 50 000 F qui sont portés au crédit de ses frais.</p><p>Le parent voit la majoration et le total débité avant de valider. Le reçu indique le montant crédité, les frais de paiement en ligne et le total débité. Les paiements enregistrés à la caisse ne sont jamais majorés.</p><p>Sans majoration, c&#39;est à l&#39;établissement d&#39;intégrer la commission dans ses tarifs.</p><h2 id="installation-autonome-configurer-vous-meme" tabindex="-1">Installation autonome : configurer vous-même <a class="header-anchor" href="#installation-autonome-configurer-vous-meme" aria-label="Permalink to &quot;Installation autonome : configurer vous-même&quot;">​</a></h2><p>Si votre établissement est seul sur son installation, la section <strong>Configuration</strong> permet de saisir vous-même le compte marchand, sans intervenir sur le serveur. Ces réglages remplacent ceux du fichier de configuration du serveur.</p><ol><li>Choisissez l&#39;<strong>Opérateur</strong>.</li><li>Saisissez la <strong>Clé d&#39;API</strong> fournie par l&#39;opérateur. Une fois enregistrée, elle n&#39;est plus jamais réaffichée : laissez le champ vide pour la conserver, ou saisissez-en une nouvelle pour la remplacer.</li><li>Indiquez la <strong>Majoration des paiements en ligne</strong>, en pourcentage (0 pour aucune).</li><li>Cochez <strong>Les parents peuvent payer en ligne</strong>.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li><li>Copiez l&#39;<strong>Adresse de retour (webhook)</strong> qui apparaît, et collez-la dans le tableau de bord de l&#39;opérateur comme adresse de confirmation des paiements. C&#39;est elle qui fait passer les paiements de « En attente » à « Payé ». Gardez-la pour vous : elle est secrète.</li></ol><p>Pour suspendre le paiement en ligne, décochez <strong>Les parents peuvent payer en ligne</strong> et enregistrez : la configuration est conservée.</p><p>Les écoles hébergées par edPage n&#39;ont pas cette section : edPage configure le compte pour elles.</p>',21)])])}const g=n(i,[["render",r]]);export{c as __pageData,g as default};
